INSERT INTO public.animal_associations (slug,name,association_type,city,postal_code,departement_code,species,description,needs,siren,rna,legal_form,website_url,facebook_url,instagram_url,donation_url,volunteer_url,contact_page_url,logo_url,tagline,founded_year,key_figures,needs_details,sources,address,contact_email,verified_at,consent_status,status,internal_note) VALUES
('emmaus-lyon','Emmaüs Lyon','solidarite','Vénissieux','69200','69','{}'::text[],'Emmaüs Lyon est une communauté d''accueil où les compagnes et les compagnons se reconstruisent en participant à la collecte, au tri, à la valorisation et à la revente des objets donnés. Quatre-vingt-dix compagnons travaillent dans le dépôt et les ateliers, et les objets sont revendus dans trois espaces : Parilly à Vénissieux, Créqui à Lyon 3 et Gratte-Ciel à Villeurbanne. Les bénévoles viennent du mardi au samedi dans les espaces de vente et au dépôt, et les dons d''objets, de meubles et de vêtements font vivre la communauté.',ARRAY['benevoles','materiel']::text[],'399493782',NULL,'Association déclarée','https://emmaus-lyon.org/','https://www.facebook.com/emmauslyon','https://www.instagram.com/emmauslyon/',NULL,'https://emmaus-lyon.org/?page_id=117','https://emmaus-lyon.org/?page_id=1157','https://emmaus-lyon.org/wp-content/uploads/2024/11/logo_Emmaus_Lyon_v3.svg','Communauté d''accueil et trois espaces de vente solidaires : bénévoles du mardi au samedi, dons d''objets bienvenus.',NULL,'[{"value": "90", "label": "compagnons dans le dépôt et les ateliers", "year": "2026", "source_url": "https://emmaus-lyon.org/?page_id=123"}, {"value": "3", "label": "espaces de vente : Parilly, Créqui et Gratte-Ciel", "year": "2026", "source_url": "https://emmaus-lyon.org/?page_id=123"}]'::jsonb,'[{"need": "benevoles", "detail": "Les bénévoles accompagnent la communauté du mardi au samedi dans les trois espaces de vente et au dépôt. Le formulaire Bénévolat de la page Nous contacter permet de proposer son aide.", "url": "https://emmaus-lyon.org/?page_id=117"}, {"need": "materiel", "detail": "Les dons d''objets, de meubles et de vêtements sont la seule ressource de la communauté. Les horaires d''accueil des dons et les adresses figurent sur la page Nous visiter (les dons textiles sont suspendus du 10 novembre au 10 décembre 2026).", "url": "https://emmaus-lyon.org/?page_id=113"}]'::jsonb,'[{"fact": "SIREN 399 493 782, association déclarée, siège à Vénissieux (vérifié à l''API officielle le 15/11/2026)", "url": "https://recherche-entreprises.api.gouv.fr/search?q=399493782"}, {"fact": "Communauté, bénévolat, dons et espaces de vente publiés par l''association", "url": "https://emmaus-lyon.org/"}]'::jsonb,NULL,NULL,'2026-11-15','pending','published','ASSO-4 vague 3 : SIREN (et RNA quand il existe) vérifiés à l''API officielle le 15/11/2026, descriptions rédigées par Guardiens, logo servi depuis le site de l''association.'),
('coup-de-pouce-universite-lyon','Coup de Pouce Université (CPU)','solidarite','Lyon','69007','69','{}'::text[],'Coup de Pouce Université accompagne à Lyon des étudiants internationaux, dont des demandeurs d''asile, tout au long de leurs études : cours et conversations en français, aide aux mémoires et aux thèses, activités culturelles. Les bénévoles animent des groupes de conversation de deux à quatre étudiants, des cours de langue ou un soutien universitaire, avec un accueil du lundi au vendredi au 1 rue Bonald (Lyon 7e), des journées pédagogiques et un repas de midi partagé entre étudiants et bénévoles. Des familles de bénévoles invitent aussi des étudiants pour faire connaître la culture française.',ARRAY['benevoles','dons']::text[],'500263785','W691068230','Association déclarée','https://www.cpu-lyon.org/wordpress/','https://www.facebook.com/CPULYON','https://www.instagram.com/cpu.lyon/','https://www.cpu-lyon.org/wordpress/index.php/nous-soutenir/','https://www.cpu-lyon.org/wordpress/index.php/benevole/','https://www.cpu-lyon.org/wordpress/index.php/contact/','https://www.cpu-lyon.org/wordpress/wp-content/uploads/2021/03/Logo-en-tete-mobile-300x109.png','Cours de français, soutien et repas partagés pour des étudiants internationaux, avec des bénévoles à Lyon 7e.',NULL,'[{"value": "120", "label": "bénévoles pour 250 étudiants accompagnés, dont 70 demandeurs d''asile", "year": "2025-2026", "source_url": "https://www.jeveuxaider.gouv.fr/missions-benevolat/108767/benevolat-coup-de-pouce-universite-1"}]'::jsonb,'[{"need": "benevoles", "detail": "L''accueil met en relation les offres des bénévoles et les besoins des étudiants selon les disponibilités. Les missions vont des groupes de conversation au soutien universitaire, et la page Bénévole explique comment s''inscrire.", "url": "https://www.cpu-lyon.org/wordpress/index.php/benevole/"}, {"need": "dons", "detail": "Le don parraine le parcours d''un étudiant ou aide un demandeur d''asile à réaliser son projet d''intégration. Un reçu fiscal est délivré aux personnes imposables en France.", "url": "https://www.cpu-lyon.org/wordpress/index.php/nous-soutenir/"}]'::jsonb,'[{"fact": "SIREN 500 263 785, RNA W691068230, association déclarée, siège à Lyon 7e (vérifié à l''API officielle le 15/11/2026)", "url": "https://recherche-entreprises.api.gouv.fr/search?q=500263785"}, {"fact": "Bénévolat, accueil, familles d''invitation et soutien publiés par l''association", "url": "https://www.cpu-lyon.org/wordpress/"}, {"fact": "Nombre de bénévoles et d''étudiants accompagnés en 2025-2026", "url": "https://www.jeveuxaider.gouv.fr/missions-benevolat/108767/benevolat-coup-de-pouce-universite-1"}]'::jsonb,NULL,'accueil@cpu-lyon.org','2026-11-15','pending','published','ASSO-4 vague 3 : SIREN (et RNA quand il existe) vérifiés à l''API officielle le 15/11/2026, descriptions rédigées par Guardiens, logo servi depuis le site de l''association.'),
('on-the-green-road','On The Green Road','nature','Lyon','69007','69','{}'::text[],'On The Green Road sensibilise à la transition écologique et solidaire par le voyage engagé et le média citoyen. L''association accompagne des voyageuses et des voyageurs dans leurs projets, organise des voyages locaux à pied, à vélo ou en train autour de Lyon, intervient dans des écoles de la métropole et porte chaque printemps le Festival du Voyage Engagé à la Maison de l''Environnement. Les bénévoles et les volontaires en service civique rejoignent l''équipe pour l''organisation du festival, l''animation de voyages locaux, la communication ou l''accompagnement de projets.',ARRAY['benevoles','dons']::text[],'750616344','W751211714','Association déclarée','https://onthegreenroad.com/','https://www.facebook.com/OnTheGreenRoad','https://www.instagram.com/on_the_green_road/','https://www.helloasso.com/associations/on-the-green-road/adhesions/formulaire-d-adhesion-2026','https://onthegreenroad.com/nous-rejoindre/','https://onthegreenroad.com/contact/','https://cdn.helloasso.com/img/logos/croppedimage-dcf4c558814148179a2fbd1a1cb55842.png','Voyages locaux à pied, à vélo ou en train, festival du voyage engagé et projets citoyens à Lyon.',NULL,'[{"value": "9", "label": "éditions du Festival du Voyage Engagé, la dernière du 17 au 19 avril 2026", "year": "2026", "source_url": "https://www.jeveuxaider.gouv.fr/organisations/10081-on-the-green-road"}, {"value": "Plus de 100", "label": "voyageuses et voyageurs accompagnés", "year": "2026", "source_url": "https://www.jeveuxaider.gouv.fr/missions-benevolat/56989/benevolat-on-the-green-road-4"}]'::jsonb,'[{"need": "benevoles", "detail": "La page Nous rejoindre présente l''équipe de bénévoles, de volontaires en service civique et de salariés. Les missions (festival, voyages locaux, communication, accompagnement de projets) sont aussi publiées sur JeVeuxAider.gouv.fr.", "url": "https://onthegreenroad.com/nous-rejoindre/"}, {"need": "dons", "detail": "L''adhésion et les dons se font en ligne sur la page HelloAsso de l''association.", "url": "https://www.helloasso.com/associations/on-the-green-road/adhesions/formulaire-d-adhesion-2026"}]'::jsonb,'[{"fact": "SIREN 750 616 344, RNA W751211714, association déclarée, siège à Lyon 7e (vérifié à l''API officielle le 15/11/2026)", "url": "https://recherche-entreprises.api.gouv.fr/search?q=750616344"}, {"fact": "Actions, équipe et festival publiés par l''association", "url": "https://onthegreenroad.com/"}, {"fact": "Missions de bénévolat et chiffres de l''association", "url": "https://www.jeveuxaider.gouv.fr/organisations/10081-on-the-green-road"}]'::jsonb,NULL,'benevolat@onthegreenroad.com','2026-11-15','pending','published','ASSO-4 vague 3 : SIREN (et RNA quand il existe) vérifiés à l''API officielle le 15/11/2026, descriptions rédigées par Guardiens, logo servi depuis le site de l''association.'),
('eco-garde-rhone','Éco-garde Rhône','nature','Lyon','69007','69','{}'::text[],'Éco-garde Rhône coordonne un dispositif de bénévoles éco-gardes pour protéger et valoriser l''environnement dans le Rhône : surveillance des espaces naturels sensibles, sensibilisation et éducation des usagers. Les éco-gardes effectuent des tournées de quatre heures le week-end, accueillent le public et veillent à la préservation des lieux. L''engagement demandé est d''environ une demi-journée par mois, et l''association recherche une dizaine de bénévoles majeurs pour 2026 et 2027.',ARRAY['benevoles']::text[],'994756070','W691112048','Association déclarée',NULL,NULL,NULL,NULL,'https://www.jeveuxaider.gouv.fr/missions-benevolat/109073/benevolat-association-eco-garde-rhone',NULL,'https://cdn.helloasso.com/img/logos/cropped-image-409662d244be4c55b3d501ef89b6e01a.png','Éco-gardes bénévoles qui surveillent et font découvrir les espaces naturels sensibles du Rhône.',2025,'[{"value": "10", "label": "bénévoles recherchés pour 2026 et 2027", "year": "2026", "source_url": "https://www.jeveuxaider.gouv.fr/missions-benevolat/109073/benevolat-association-eco-garde-rhone"}]'::jsonb,'[{"need": "benevoles", "detail": "Une demi-journée par mois, du 1er septembre 2026 au 31 décembre 2027, pour surveiller et faire découvrir les espaces naturels sensibles. La mission se présente et se réserve sur JeVeuxAider.gouv.fr.", "url": "https://www.jeveuxaider.gouv.fr/missions-benevolat/109073/benevolat-association-eco-garde-rhone"}]'::jsonb,'[{"fact": "SIREN 994 756 070, RNA W691112048, association déclarée, créée en novembre 2025, siège à Lyon 7e (vérifié à l''API officielle le 15/11/2026)", "url": "https://recherche-entreprises.api.gouv.fr/search?q=994756070"}, {"fact": "Objet, missions et besoins en bénévoles publiés sur JeVeuxAider.gouv.fr", "url": "https://www.jeveuxaider.gouv.fr/organisations/36398-association-eco-garde-rhone"}, {"fact": "Rôle des éco-gardes et tournées de quatre heures le week-end", "url": "https://www.mairie-francheville69.fr/wp-content/uploads/2023/09/Flyer-ECO-GARDE.pdf"}]'::jsonb,NULL,'ecogardes69@gmail.com','2026-11-15','pending','published','ASSO-4 vague 3 : SIREN (et RNA quand il existe) vérifiés à l''API officielle le 15/11/2026, descriptions rédigées par Guardiens, logo servi depuis le site de l''association.'),
('afe-apprendre-le-francais-ensemble-lyon','AFE, Apprendre le Français Ensemble','solidarite','Lyon','69003','69','{}'::text[],'AFE, Apprendre le Français Ensemble, est une association lyonnaise qui accueille chaque lundi de 18h45 à 20h, dans trois salles de cours près du métro Sans-Souci (25 rue du Dauphiné, Lyon 3e), des personnes primo-arrivantes, demandeuses d''asile ou réfugiées et des travailleurs étrangers qui ne peuvent pas apprendre le français en journée. Les bénévoles les aident à déchiffrer l''alphabet, à parler et à écrire, dans un bénévolat sans engagement : on vient quand on peut, quand on veut.',ARRAY['benevoles']::text[],'931258016','W691109562','Association déclarée',NULL,NULL,NULL,NULL,'https://www.jeveuxaider.gouv.fr/missions-benevolat/86697/benevolat-afe-lyon-apprendre-le-francais-ensemble-1',NULL,NULL,'Ateliers de français chaque lundi soir à Lyon 3e pour personnes nouvellement arrivées, bénévolat sans engagement.',2021,'[{"value": "2021", "label": "année depuis laquelle l''association intervient à Lyon", "year": "2026", "source_url": "https://www.jeveuxaider.gouv.fr/missions-benevolat/88971/benevolat-afe-lyon-apprendre-le-francais-ensemble-2"}]'::jsonb,'[{"need": "benevoles", "detail": "Les ateliers ont lieu chaque lundi de 18h45 à 20h, au 25 rue du Dauphiné à Lyon 3e (tramway Dauphiné-Lacassagne ou métro D Sans-Souci). La mission est présentée et réservable sur JeVeuxAider.gouv.fr.", "url": "https://www.jeveuxaider.gouv.fr/missions-benevolat/86697/benevolat-afe-lyon-apprendre-le-francais-ensemble-1"}]'::jsonb,'[{"fact": "SIREN 931 258 016, RNA W691109562, association déclarée, enregistrée à Lyon (vérifié à l''API officielle le 15/11/2026)", "url": "https://recherche-entreprises.api.gouv.fr/search?q=931258016"}, {"fact": "Ateliers du lundi, public accueilli et missions de bénévolat publiés sur JeVeuxAider.gouv.fr", "url": "https://www.jeveuxaider.gouv.fr/organisations/15258-afe-lyon-apprendre-le-francais-ensemble"}]'::jsonb,NULL,NULL,'2026-11-15','pending','published','ASSO-4 vague 3 : SIREN (et RNA quand il existe) vérifiés à l''API officielle le 15/11/2026, descriptions rédigées par Guardiens, logo servi depuis le site de l''association.')
